#include <BLEDevice.h>
#include <BLEServer.h>
#include <BLEUtils.h>

#define LED_PIN 8  // Common onboard LED pin on ESP32-C3 Super Mini

class LEDCallbacks : public BLECharacteristicCallbacks {
  void onWrite(BLECharacteristic *pCharacteristic) override {
    String value = pCharacteristic->getValue();
    value.trim();
    value.toUpperCase();

    if (value == "ON") {
      digitalWrite(LED_PIN, LOW);   // Active-low LED
    } else if (value == "OFF") {
      digitalWrite(LED_PIN, HIGH);
    }
  }
};

void setup() {
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, HIGH);     // Start with LED off

  BLEDevice::init("ESP32_LED");

  BLEServer *server = BLEDevice::createServer();
  BLEService *service = server->createService(
    "12345678-1234-1234-1234-123456789000"
  );

  BLECharacteristic *characteristic = service->createCharacteristic(
    "12345678-1234-1234-1234-123456789001",
    BLECharacteristic::PROPERTY_WRITE
  );

  characteristic->setCallbacks(new LEDCallbacks());
  service->start();

  BLEAdvertising *advertising = BLEDevice::getAdvertising();
  advertising->addServiceUUID("12345678-1234-1234-1234-123456789000");
  advertising->start();
}

void loop() {
  delay(100);
}
